begin;
create or replace function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end$$;
insert into auth.users(id) values ('11050100-0000-4000-8000-000000000001'),('11050100-0000-4000-8000-000000000002'),('11050100-0000-4000-8000-000000000003'),('11050100-0000-4000-8000-000000000004');
insert into public.user_roles(user_id,role) values ('11050100-0000-4000-8000-000000000001','professional'),('11050100-0000-4000-8000-000000000003','professional');
insert into public.professional_profiles(user_id,professional_name) values ('11050100-0000-4000-8000-000000000001','Histórico');
update public.profiles set display_name='Ana Direta' where id='11050100-0000-4000-8000-000000000002';
update public.profiles set display_name='Bia Solicitação' where id='11050100-0000-4000-8000-000000000004';
select pg_temp.assert_true(not has_function_privilege('anon','public.professional_generated_invites()','EXECUTE'),'anonymous cannot read history');
select pg_temp.assert_true(not has_function_privilege('anon','public.delete_revoked_professional_invite(uuid)','EXECUTE'),'anonymous cannot delete invitations');
set local role authenticated;
select set_config('request.jwt.claim.sub','11050100-0000-4000-8000-000000000001',true);
do $$
declare available public.professional_invites; revoked public.professional_invites; direct public.professional_invites; requested public.professional_invites; request_id uuid; relationship_id uuid; data jsonb;
begin
  available:=public.create_professional_invite('code');
  revoked:=public.create_professional_invite('code');
  direct:=public.create_professional_invite('code');
  requested:=public.create_professional_invite('code');
  perform public.revoke_professional_invite(revoked.id);
  begin perform public.delete_revoked_professional_invite(available.id); raise exception 'deleted active invite'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub','11050100-0000-4000-8000-000000000002',true);
  perform public.accept_professional_invite(direct.code);
  begin perform public.professional_generated_invites(); raise exception 'student read professional history'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub','11050100-0000-4000-8000-000000000004',true);
  request_id:=(public.request_professional_link(requested.code)).id;
  perform set_config('request.jwt.claim.sub','11050100-0000-4000-8000-000000000001',true);
  relationship_id:=(public.accept_professional_link_request(request_id)).id;
  data:=public.professional_generated_invites();
  perform pg_temp.assert_true(jsonb_array_length(data)=4,'only generated invitations are listed');
  perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(data) i where i->>'id'=direct.id::text and (i->>'is_used')::boolean and i->>'used_by_name'='Ana Direta'),'direct acceptance exposes the actual user name');
  perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(data) i where i->>'id'=requested.id::text and (i->>'is_used')::boolean and i->>'used_by_name'='Bia Solicitação' and i->>'used_at' is not null),'request acceptance exposes the actual user and date even when raw status is pending');
  begin perform public.delete_revoked_professional_invite(direct.id); raise exception 'deleted used invite'; exception when insufficient_privilege then null; end;
  perform public.revoke_professional_invite(requested.id);
  begin perform public.delete_revoked_professional_invite(requested.id); raise exception 'deleted invitation with accepted request'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub','11050100-0000-4000-8000-000000000003',true);
  perform pg_temp.assert_true(public.professional_generated_invites()='[]'::jsonb,'history does not expose another professional users');
  begin perform public.delete_revoked_professional_invite(revoked.id); raise exception 'deleted another owner invitation'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub','11050100-0000-4000-8000-000000000001',true);
  perform pg_temp.assert_true(public.delete_revoked_professional_invite(revoked.id),'owner can delete an unused revoked invite');
  perform pg_temp.assert_true(not exists(select 1 from public.professional_invites where id=revoked.id),'deleted invite is absent');
  perform pg_temp.assert_true(exists(select 1 from public.professional_student_relationships where id=relationship_id and status='active'),'relationship survives history deletion');
  perform pg_temp.assert_true(exists(select 1 from public.profiles where id='11050100-0000-4000-8000-000000000004'),'student profile survives history deletion');
  begin perform public.delete_revoked_professional_invite(revoked.id); raise exception 'deleted nonexistent invitation'; exception when insufficient_privilege then null; end;
end $$;
rollback;
